(() => {
  const escapeHtml = (value) =>
    value
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

  const highlightText = (text) => {
    const escaped = escapeHtml(text);
    const pattern = /(&lt;\?php|&lt;\?|\\?&gt;)|(\/\*[\s\S]*?\*\/|\/\/.*?$|#.*?$)|("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|\b(class|function|public|private|protected|final|static|if|else|elseif|foreach|for|while|return|new|try|catch|throw|switch|case|default)\b|(&lt;\/?[a-zA-Z][^&]*?&gt;)/gm;
    let result = '';
    let lastIndex = 0;
    let match;

    while ((match = pattern.exec(escaped)) !== null) {
      result += escaped.slice(lastIndex, match.index);
      if (match[1]) {
        result += `<span class="hljs-meta">${match[1]}</span>`;
      } else if (match[2]) {
        result += `<span class="hljs-comment">${match[2]}</span>`;
      } else if (match[3]) {
        result += `<span class="hljs-string">${match[3]}</span>`;
      } else if (match[4]) {
        result += `<span class="hljs-keyword">${match[4]}</span>`;
      } else if (match[5]) {
        result += `<span class="hljs-tag">${match[5]}</span>`;
      }
      lastIndex = match.index + match[0].length;
    }

    result += escaped.slice(lastIndex);
    return result;
  };

  const highlightElement = (element) => {
    if (!element) {
      return;
    }
    const text = element.textContent || '';
    element.classList.add('hljs');
    element.innerHTML = highlightText(text);
  };

  window.hljs = {
    highlightElement,
  };
})();
